// This style of import is necessary for storybook to automatically generate the documentation for prop types and control interface
import * as React from "react";
import "./Breadcrumb.scss";
import clsx from "clsx";
import Crumb from "./Crumb/Crumb";
import { SvgMpaIcon } from "../../assets/icons";
import useWindowSize from "../../hooks/useWindowSize";
import TruncatedMenu from "./Truncated/TruncatedMenu";

export interface CrumbType {
  label: string;
  to: string;
}

export interface BreadcrumbProps {

  hoverStyle?: "normal" | "underline";
  /**
   * Colour variant
   * @default "link"
   */
  colour?: "link" | "black" | "white";
  /**
   * Icon to display for the home link. Should be a key from SvgMpaIcon
   */
  homeIcon?: keyof typeof SvgMpaIcon;
  /**
   * Whether to show the "Home" label next to the home icon
   * @default false
   */
  showHomeLabel?: boolean;
  /**
   * Show last (i.e current page) breadcrumb as a page title
   * @default false
   */
  multiline?: boolean;
  /**
   * Force truncated view even on desktop screens
   * @default false
   */
  forceTruncated?: boolean;
  /**
   * Icon to use for the truncated menu button
   * @default "MoreHorizontal"
   */
  truncatedButtonIcon?: keyof typeof SvgMpaIcon;
  /**
   * Label for the truncated menu button
   */
  truncatedButtonLabel?: string;
  /**
   * Custom link component for navigation (e.g. React Router Link)
   */
  LinkComponent?: React.ComponentType<any>;
  /**
   * Separator element between breadcrumbs
   * @default "ChevronRight"
   */
  separator?: React.ReactNode;
  /**
   * Array of breadcrumb items to display
   */
  routes: CrumbType[];
  /**
   * Additional custom className for the container
   */
  className?: string;
}

const Breadcrumb: React.FC<BreadcrumbProps> = ({
  hoverStyle,
  colour = "link",
  homeIcon,
  showHomeLabel,
  multiline = false,
  forceTruncated = false,
  truncatedButtonIcon,
  truncatedButtonLabel,
  LinkComponent,
  separator = "ChevronRight",
  routes = [],
  className,
}) => {
  const total = routes.length;
  const showSeparator = (i: number) => {
    if (multiline) return i < total - 2;
    return i < total - 1;
  };
  const { isMobile } = useWindowSize();
  const isTruncate = routes.length - 3 > 0 && (forceTruncated || isMobile);
  const truncate = () => {
    const first = routes[0];
    const last = routes[routes.length - 1];
    const mids = routes
      .filter((_, i) => i > 0 && i < routes.length - 1)
      .map(({ label, to }) => ({ LinkComponent, label, link: to }));

    return (
      <>
        <Crumb
          colour={colour}
          homeIcon={homeIcon}
          showHomeLabel={showHomeLabel}
          showSeparator
          multiline={false}
          isFirst
          isLast={false}
          LinkComponent={LinkComponent}
          separator={separator}
          label={first.label}
          to={first.to}
          hoverStyle={hoverStyle}
        />
        <TruncatedMenu
          colour={colour}
          separator={separator}
          icon={truncatedButtonIcon}
          label={truncatedButtonLabel}
          menuItems={mids}
          hoverStyle={hoverStyle}
        />
        <Crumb
          colour={colour}
          homeIcon={homeIcon}
          showHomeLabel={showHomeLabel}
          showSeparator={false}
          multiline={false}
          isFirst={false}
          isLast
          LinkComponent={LinkComponent}
          separator={separator}
          label={last.label}
          to={last.to}
          hoverStyle={hoverStyle}
        />
      </>
    );
  };
  const full = () => {
    return routes.map((c, i) => {
      const isFirst = i === 0;
      const isLast = i === total - 1;

      return (
        <Crumb
          key={`${i}-${c.label}`}
          colour={colour}
          homeIcon={homeIcon}
          showHomeLabel={showHomeLabel}
          showSeparator={showSeparator(i)}
          multiline={multiline}
          isFirst={isFirst}
          isLast={isLast}
          LinkComponent={LinkComponent}
          separator={separator}
          label={c.label}
          to={c.to}
          hoverStyle={hoverStyle}
        />
      );
    });
  };
  return (
    <div className={clsx("breadcrumb-base", colour, !!className && className) }>
      <ol
        className={clsx("breadcrumb-ol", { "breadcrumb-multiline": multiline })}
      >
        {isTruncate ? truncate() : full()}
      </ol>
      {multiline && !isTruncate && !!total && (
        <h4 className="breadcrumb-header">{routes[total - 1].label}</h4>
      )}
    </div>
  );
};

export default Breadcrumb;
